"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, useId, useLayoutEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** One notification in the stack. */
export interface StackNotification {
  id: string;
  /** One line. A longer title is cut with an ellipsis, because every card has the same height. */
  title: string;
  /** One line of detail under the title. */
  body?: string;
  /** When it arrived, already worded, for example "2 min ago". */
  time?: string;
}

/**
 * Props for a notification stack. Pass `items` and `expanded` to control it,
 * or the `default` props to let it hold its own state. Items are newest first.
 */
export type NotificationStackProps = Omit<ComponentPropsWithoutRef<"section">, "children"> & {
  items?: StackNotification[];
  defaultItems?: StackNotification[];
  onItemsChange?: (items: StackNotification[]) => void;
  expanded?: boolean;
  defaultExpanded?: boolean;
  onExpandedChange?: (expanded: boolean) => void;
  /** Names the region for screen readers and shows above the stack. */
  label?: string;
};

// Damping 40 is 2 × √400: critically damped, so a card slides to its place and stops.
const MOVE: Transition = { type: "spring", stiffness: 400, damping: 40, mass: 1 };
const LEAVE: Transition = { duration: 0.15, ease: [0.165, 0.84, 0.44, 1] };
// Reduced motion places each card at once and keeps a short fade.
const REDUCED: Transition = { duration: 0, opacity: { duration: 0.15 } };

// Every card is 4rem tall, so each place in the pile is known without measuring.
const CARD = 4;
const GAP = 0.5;
const PEEK = 0.5;
const SHRINK = 0.05;
const BEHIND = 2;
const rem = (value: number) => `${value}rem`;

const ACTION =
  "relative min-h-9 cursor-pointer touch-manipulation rounded-full px-3 text-sm font-medium text-muted-foreground outline-none before:absolute before:inset-x-0 before:-inset-y-1 hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring motion-safe:transition-colors";

/**
 * Piles notifications with only the newest in full view. Pressing the pile
 * spreads it into a list; a dismissed card leaves and the rest close the gap.
 */
export function NotificationStack({
  items,
  defaultItems = [],
  onItemsChange,
  expanded,
  defaultExpanded = false,
  onExpandedChange,
  label = "Notifications",
  className,
  onKeyDown,
  ...sectionProps
}: NotificationStackProps) {
  const [ownItems, setOwnItems] = useState(defaultItems);
  const [ownExpanded, setOwnExpanded] = useState(defaultExpanded);
  const current = items ?? ownItems;
  const count = current.length;
  // One card has nothing behind it, so it always shows as a list of one.
  const spread = (expanded ?? ownExpanded) || count <= 1;
  const reduceMotion = useReducedMotion();
  const listId = useId();

  // A card that was not here on the last render is new, so it is announced.
  const [known, setKnown] = useState(current);
  const [announcement, setAnnouncement] = useState("");
  if (known !== current) {
    setKnown(current);
    const fresh = current.find((item) => !known.some((old) => old.id === item.id));
    if (fresh) setAnnouncement(`New notification: ${fresh.title}`);
  }

  const region = useRef<HTMLElement>(null);
  const pile = useRef<HTMLButtonElement>(null);
  const collapse = useRef<HTMLButtonElement>(null);
  const dismissers = useRef(new Map<string, HTMLButtonElement>());
  // The pressed control often leaves the page, so focus is handed to what replaces it.
  const focusNext = useRef<string | null>(null);

  useLayoutEffect(() => {
    const target = focusNext.current;
    if (!target) return;
    focusNext.current = null;
    const node =
      target === "pile" ? pile.current : target === "collapse" ? collapse.current : dismissers.current.get(target);
    (node ?? region.current)?.focus({ preventScroll: true });
  });

  const setItems = (next: StackNotification[]) => {
    if (items === undefined) setOwnItems(next);
    onItemsChange?.(next);
  };

  const setExpanded = (next: boolean) => {
    focusNext.current = next ? "collapse" : "pile";
    if (expanded === undefined) setOwnExpanded(next);
    onExpandedChange?.(next);
  };

  const dismiss = (id: string) => {
    const index = current.findIndex((item) => item.id === id);
    const next = current.filter((item) => item.id !== id);
    focusNext.current = (next[index] ?? next[index - 1])?.id ?? "region";
    setItems(next);
  };

  const clearAll = () => {
    setExpanded(false);
    focusNext.current = "region";
    setItems([]);
  };

  const height = spread ? count * CARD + Math.max(count - 1, 0) * GAP : CARD + Math.min(count - 1, BEHIND) * PEEK;

  return (
    <section
      {...sectionProps}
      ref={region}
      aria-label={label}
      tabIndex={-1}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (event.defaultPrevented || event.key !== "Escape" || !spread || count <= 1) return;
        setExpanded(false);
      }}
      className={cn("flex w-full max-w-sm flex-col gap-2 rounded-2xl text-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-4 focus-visible:ring-offset-background", className)}
    >
      <div className="flex min-h-9 items-center gap-2 px-1 text-sm">
        <p className="font-medium">{label}</p>
        <span className="rounded-full bg-muted px-2 py-0.5 text-xs font-medium tabular-nums">{count}</span>
        {spread && count > 1 ? (
          <span className="ml-auto flex gap-1">
            <button ref={collapse} type="button" aria-expanded="true" aria-controls={listId} onClick={() => setExpanded(false)} className={ACTION}>
              Show less
            </button>
            <button type="button" onClick={clearAll} className={ACTION}>
              Clear all
            </button>
          </span>
        ) : null}
      </div>

      <div className="relative">
        <motion.ul
          id={listId}
          initial={false}
          animate={{ height: rem(Math.max(height, CARD)) }}
          transition={reduceMotion ? REDUCED : MOVE}
          // The list isolates its cards' stacking order, so the pile button after it stays on top.
          className="relative isolate"
        >
          <AnimatePresence initial={false}>
            {current.map((item, index) => {
              const depth = spread ? 0 : Math.min(index, BEHIND);
              const hidden = !spread && index > 0;
              return (
                <motion.li
                  key={item.id}
                  aria-hidden={hidden || undefined}
                  initial={{ opacity: 0, y: rem(reduceMotion ? 0 : -CARD / 2), scale: 1 }}
                  animate={{
                    opacity: !spread && index > BEHIND ? 0 : 1,
                    y: rem(spread ? index * (CARD + GAP) : depth * PEEK),
                    scale: 1 - depth * SHRINK,
                  }}
                  exit={{ opacity: 0, x: reduceMotion ? 0 : 24, transition: LEAVE }}
                  transition={reduceMotion ? REDUCED : MOVE}
                  // Motion owns the transform, so the stacking order rides along with it.
                  style={{ zIndex: count - index }}
                  className="absolute inset-x-0 top-0 flex h-16 origin-bottom items-center gap-3 rounded-2xl border border-border bg-card px-4 shadow-sm"
                >
                  <div className="min-w-0 flex-1">
                    <p className="flex items-baseline gap-2 text-sm">
                      <span className="truncate font-medium">{item.title}</span>
                      {item.time ? <span className="shrink-0 text-xs text-muted-foreground">{item.time}</span> : null}
                    </p>
                    {item.body ? <p className="truncate text-sm text-muted-foreground">{item.body}</p> : null}
                  </div>
                  {spread ? (
                    <button
                      ref={(node) => {
                        if (node) dismissers.current.set(item.id, node);
                        else dismissers.current.delete(item.id);
                      }}
                      type="button"
                      aria-label={`Dismiss: ${item.title}`}
                      onClick={() => dismiss(item.id)}
                      // The button is 28px wide; the pseudo-element grows the hit area to 44px.
                      className="relative grid size-7 shrink-0 cursor-pointer touch-manipulation place-items-center rounded-full text-muted-foreground outline-none before:absolute before:-inset-2 hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring motion-safe:transition-colors"
                    >
                      <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden="true" className="size-3.5">
                        <path d="m4 4 8 8M12 4l-8 8" />
                      </svg>
                    </button>
                  ) : null}
                </motion.li>
              );
            })}
          </AnimatePresence>
        </motion.ul>

        {count === 0 ? (
          <p className="absolute inset-0 grid place-items-center rounded-2xl border border-dashed border-border text-sm text-muted-foreground">
            You are all caught up
          </p>
        ) : null}

        {spread ? null : (
          // One button covers the pile, so a press anywhere on it spreads the list.
          <button
            ref={pile}
            type="button"
            aria-expanded="false"
            aria-controls={listId}
            aria-label={`Show all ${count} notifications`}
            onClick={() => setExpanded(true)}
            className="absolute inset-0 cursor-pointer touch-manipulation rounded-2xl outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
          />
        )}
      </div>

      <p role="status" aria-live="polite" className="sr-only">
        {announcement}
      </p>
    </section>
  );
}
